import json, numpy as np, netCDF4 as nc
def fields(path):
    d = nc.Dataset(path)
    names = [''.join(c.decode() if isinstance(c,bytes) else c for c in row).strip() for row in d.variables['name_nod_var'][:]]
    out = {n: d.variables['vals_nod_var%d' % (i+1)][:] for i,n in enumerate(names)}
    t = d.variables['time_whole'][:]
    return names, out, np.array(t)
n1, f1, t1 = fields('outputs/stage1/engine_output.exo')
n2, f2, t2 = fields('work/stage2/engine_output.exo')
res = {'checkpoint': 'outputs/stage1/engine_output.exo', 'stage2_engine_output': 'work/stage2/engine_output.exo',
       'checkpoint_time_steps': int(len(t1)), 'stage2_time_steps': int(len(t2)), 'fields': {}}
for n in ('control','topology'):
    a = np.asarray(f1[n][20]); b = np.asarray(f2[n][0]); c = np.asarray(f1[n][19])
    res['fields'][n] = {
      'checkpoint_step21_iter20_vs_stage2_step1_iter0_max_abs_diff': float(np.max(np.abs(a-b))),
      'checkpoint_step20_iter19_vs_stage2_step1_iter0_max_abs_diff': float(np.max(np.abs(c-b))),
      'identical_to_iter20': bool(np.array_equal(a,b)),
      'checkpoint_iter20_min_max': [float(a.min()), float(a.max())],
      'stage2_iter0_min_max': [float(b.min()), float(b.max())]}
print(json.dumps(res, indent=1))
EOF
echo "$(date -u -Is) field check: checkpoint control step21 vs stage2 engine_output step1 -> work/verify/stage2_field_continuation.json" >> work/notes.log

